import json,pathlib
r=pathlib.Path(__file__).resolve().parents[2];c=json.loads((r/'tests/homologation/catalog-a.json').read_text());p=next(p for p in c['products'] if p['name']=='Produto ficticio A');p['price']=30;p['metadata']['options']=[]
item=dict(selectionContract='GROUP_ADDONS_V1',groupAddonIds=[c['addon_groups'][0]['addons'][0]['id']],lineId='test-line',productId=p['id'],productName=p['name'],imageUrl=None,secondProductId=None,secondProductName=None,isHalf=False,sizeId=None,sizeName=None,crustId=None,crustName=None,crustPrice=0,addons=[],complements=[],quantity=1,notes=None,unitPrice=30)
script="import React,{useState} from 'react';import {createRoot} from 'react-dom/client';import {CheckoutPanel} from '/src/features/storefront/components/CheckoutPanel';import '/src/styles.css';import {reviewCartPrices} from '/src/core/delivery/review-cart-prices';const catalog="+json.dumps(c)+";const item="+json.dumps(item)+";function App(){const [items,setItems]=useState([item]);return <div className='ppp-customer-shell'><CheckoutPanel organization={{id:catalog.context.organization_id,name:'Loja fictícia A'}} groupCatalog={catalog} instanceId={catalog.context.instance_id} storeDomain='a.ab.invalid' settings={catalog.settings} deliveryZones={catalog.delivery_zones} items={items} subtotal={items.reduce((s,i)=>s+i.unitPrice*i.quantity,0)} storeOpen={true} storeStatusLabel='Fixture aberta' onClose={()=>{}} onSuccess={()=>{document.title='Pedido confirmado'}} onReviewPrices={async()=>{await new Promise(r=>setTimeout(r,200));if(new URLSearchParams(location.search).has('failReview'))throw Error('Catálogo indisponível fictício');catalog.products.find(p=>p.id===item.productId).price=35;catalog.delivery_zones[0].delivery_fee=6;setItems(reviewCartPrices([item],catalog,catalog.context.instance_id))}}/></div>}createRoot(document.getElementById('root')).render(<App/>);"
(r/'homologation-harness.tsx').write_text(script);(r/'homologation-harness.html').write_text('<html><div id="root"></div><script type="module" src="/homologation-harness.tsx"></script></html>')
